item.content:encoded:
.home .bdt-navbar-nav > li > a {
	color: #fff !important;
}

.wpdiscuz-sort-buttons .wpdiscuz-sort-button.wpdiscuz-date-sort-asc.wpdiscuz-sort-button-active {
	color: #192744 !important;
}

#wpcomm .wpdiscuz-sort-button:hover {
	color: #ec2552 !important;
}

#wpcomm .wc-footer-left .wc-reply-button {  
	color: #192744 !important;
	border: 1px solid #192744!important;
}

.wc-reply-button.wc-cta-button {
	border-color: #192744 !important;
}

 #wpcomm .wc-cta-button:hover {

    background: transparent!important;
    color: #ec2552 !important;
    border-color: #ec2552 !important;
}

#wpcomm .wpdiscuz-sort-button-active,
.wpdiscuz-sort-button.wpdiscuz-date-sort-asc.wpdiscuz-sort-button-active,
.wc-blog-guest.wc-comment-label,
.wc-comment-header .wc-comment-author {
    color: #192744 !important;
}

#wpcomm .wc-footer-right .wc-toggle,
#wpcomm .wc-footer-right .wc-toggle a,
#wpcomm .wc-footer-right .wc-toggle i {
	  color: #192744 !important;
}

#wpcomm .wpf-cta:hover {
    background: transparent!important;
    color: #ec2552;
}
#wpcomm .wc-blog-post_author > .wc-comment-right .wc-comment-author, #wpcomm .wc-blog-post_author > .wc-comment-right .wc-comment-author a,
#wpcomm .wc-blog-post_author > .wc-comment-left .wc-comment-label {
	 color: #192744 !important;
}

.elementor-background-slideshow__slide__image {
	position: relative;
}


.elementor-background-slideshow .elementor-background-slideshow__slide .elementor-background-slideshow__slide__image::before {
	content: '';
	position:absolute;
	width: 100%;
	height: 100%;
	background: rgba( 0, 0, 0, 0.2 );
} 

@media screen and (max-device-width: 1024px) and (min-device-width: 992px) {
	.elementor-widget-container .cakelements-burger-menu__container[style] {
			width: 40vw!important;
			left: unset!important;
			right: 0!important;
	}

}

@media screen and (max-width: 1024px) and (min-width: 992px) {
	.elementor-widget-container .cakelements-burger-menu__container[style] {
			width: 40vw!important;
			left: unset!important;
			right: 0!important;
	}

}

.wpcf7-form .input_label {
	display: none !important;
}

.newsletter .elementor-widget-container .elementor-shortcode .invalid .wpcf7-response-output {
	display: none !important;
}

.newsletter .elementor-widget-container .elementor-shortcode .invalid input {
	border: 1px solid #ec2552;
}

.bdt-navbar-parent-indicator-yes ul>li.bdt-parent>a:after {
    content: '\e911'!important;
    font-family: 'element-pack' !important;
}

.bdt-navbar-parent-indicator-yes .bdt-navbar-dropdown-nav>li.bdt-parent>a:after {
    position: absolute;
    transform: translate(-50%,-50%);
    transform-origin: center;
    top: calc(50% + 1px);
    content: "\e925" !important;
    right: 0;
    margin: 0;
}

.home .bdt-navbar-nav>li.bdt-active>a::before {
  background-color: #fff !important;
}

.home .bdt-navbar-nav>li>a {
  color: #fff !important;
}

.wpdiscuz-sort-buttons .wpdiscuz-sort-button.wpdiscuz-date-sort-asc.wpdiscuz-sort-button-active {
  color: #192744 !important;
}

#wpcomm .wpdiscuz-sort-button:hover {
  color: #ec2552 !important;
}

#wpcomm .wc-footer-left .wc-reply-button {
  color: #192744 !important;
  border: 1px solid #192744 !important;
}

.wc-reply-button.wc-cta-button {
  border-color: #192744 !important;
}

#wpcomm .wc-cta-button:hover {
  background: transparent !important;
  color: #ec2552 !important;
  border-color: #ec2552 !important;
}

#wpcomm .wpdiscuz-sort-button-active,
.wpdiscuz-sort-button.wpdiscuz-date-sort-asc.wpdiscuz-sort-button-active,
.wc-blog-guest.wc-comment-label,
.wc-comment-header .wc-comment-author {
  color: #192744 !important;
}

#wpcomm .wc-footer-right .wc-toggle,
#wpcomm .wc-footer-right .wc-toggle a,
#wpcomm .wc-footer-right .wc-toggle i {
  color: #192744 !important;
}

#wpcomm .wpf-cta:hover {
  background: transparent !important;
  color: #ec2552;
}

#wpcomm .wc-blog-post_author>.wc-comment-right .wc-comment-author,
#wpcomm .wc-blog-post_author>.wc-comment-right .wc-comment-author a,
#wpcomm .wc-blog-post_author>.wc-comment-left .wc-comment-label {
  color: #192744 !important;
}

.elementor-background-slideshow__slide__image {
  position: relative;
}

.elementor-background-slideshow .elementor-background-slideshow__slide .elementor-background-slideshow__slide__image::before {
  content: '';
  position: absolute;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.2);
}

@media (min-width: 768px) {
  .home .cakelements-burger-menu-toggle-container .toggle-button {
    color: #fff !important;
  }
}

@media screen and (max-device-width: 1024px) and (min-device-width: 992px) {
  .elementor-widget-container .cakelements-burger-menu__container[style] {
    width: 40vw !important;
    left: unset !important;
    right: 0 !important;
  }
}

@media screen and (max-width: 1024px) and (min-width: 992px) {
  .elementor-widget-container .cakelements-burger-menu__container[style] {
    width: 40vw !important;
    left: unset !important;
    right: 0 !important;
  }
}

.wpcf7-form .input_label {
  display: none !important;
}

/* .newsletter .elementor-widget-container .elementor-shortcode .invalid .wpcf7-response-output {
	display: none !important;
} */

div.wpcf7-validation-errors,
span.wpcf7-not-valid-tip {
  display: block !important;
  text-align: initial !important;
}

.inner-footer-newsletter .wpcf7-not-valid-tip {
  color: yellow !important;
}

.invalid input[type=submit].contact-btn {
  border-color: #ec2552 !important;
}

/* 
.request-for-quote .contact-btn {
	text-align: left !important;
} */

.newsletter .elementor-widget-container .elementor-shortcode .invalid input {
  border: 1px solid #ec2552;
}

.bdt-navbar-parent-indicator-yes ul>li.bdt-parent>a:after {
  content: '\e911' !important;
  font-family: 'element-pack' !important;
}

.bdt-navbar-parent-indicator-yes .bdt-navbar-dropdown-nav>li.bdt-parent>a:after {
  position: absolute;
  transform: translate(-50%, -50%);
  transform-origin: center;
  top: calc(50% + 1px);
  content: "\e925" !important;
  right: 0;
  margin: 0;
}

span.bdt-ep-advanced-icon-box-icon-wrap svg {
  width: 64px;
  height: 64px;
}

.footer-newsletter {
  width: 100% !important;
  padding: 10px !important;
}

input[type=submit].footer-newsletter-btn {
  opacity: 1;
  font-weight: 400 !important;
}

input[type=submit].footer-newsletter-btn::before {
  display: none !important;
}

/* form-sent */
.wpcf7-spinner,
.wpcf7-response-output {
  display: none !important;
}

.wpcf7 form.sent .wpcf7-response-output {
  color: #46b450;
  border: 0;
  margin: 0;
  padding: 0;
  display: block !important;
}

.bdt-post-slider.bdt-post-slider-skin-hazel .bdt-post-slider-thumbnail img {
  height: 100%;
  position: absolute;
}

.bdt-post-slider.bdt-post-slider-skin-hazel .bdt-post-slider-thumbnail~div {
  background-color: #192744;
}

.bdt-post-slider-skin-hazel .bdt-post-slider-navigation-inner a {
  color: #fff !important;
  background-color: #ec2552 !important;
}

.bdt-post-slider.bdt-post-slider-skin-hazel .bdt-post-slider-navigation .bdt-post-slider-navigation-inner a {
  padding: 10px 15px;
  font-size: 12px;
  font-weight: 700;
  color: #999;
  background-color: #222;
  text-align: center;
  transition: background-color 300ms ease-out;
  position: relative;
}

.bdt-post-slider.bdt-post-slider-skin-hazel .bdt-post-slider-navigation .bdt-post-slider-navigation-inner a svg {
  height: 10px;
  width: auto;
}

.bdt-post-slider.bdt-post-slider-skin-hazel .bdt-post-slider-navigation .bdt-post-slider-navigation-inner a:first-child:after {
  content: '';
  width: 1px;
  height: 100%;
  position: absolute;
  right: 0;
  top: 0;
  background-color: rgba(255, 255, 255, .3);
}

.bdt-post-slider-skin-hazel .bdt-post-slider-navigation-inner a svg polyline {
  stroke: #fff;
}

.bdt-post-slider.bdt-post-slider-skin-hazel .bdt-post-slider-navigation .bdt-post-slider-navigation-inner a span {
  margin: 0 5px;
}

@media screen and (min-width: 768px) {
  .bdt-post-slider.bdt-post-slider-skin-hazel .bdt-post-slider-navigation .bdt-post-slider-navigation-inner a {
    padding: 15px 20px;
    font-size: 13px;
  }

  .bdt-post-slider.bdt-post-slider-skin-hazel .bdt-post-slider-navigation .bdt-post-slider-navigation-inner a svg {
    height: 12px;
  }

  .bdt-post-slider.bdt-post-slider-skin-hazel .bdt-post-slider-navigation .bdt-post-slider-navigation-inner a span {
    margin: 0 8px;
  }
}


/* RTL VERSION */
.rtl .banner-slide .elementor-background-overlay {
	transform: rotateY(180deg);
}

.rtl .banner-slide .elementor-background-slideshow__slide__image {
  transform: rotateY(180deg);
}

.rtl .icon_box2 .bdt-ep-advanced-icon-box-icon {
	margin-left: 30px;
}

.rtl .wpcf7 {
	direction: rtl;
}

.rtl .wpcf7-email {
	text-align: right;
}

.rtl .selectric-wpcf7-form-control .selectric .button {
	left: 2px;
	right: auto;
}

.rtl .selectric .label {
	margin-right: 0;
}

.rtl input[type=submit].footer-newsletter-btn {
	left: 0;
	right: auto;
}

.rtl .bdt-post-slider-content .bdt-post-slider-title-wrap a .bdt-post-slider-title::after,
.rtl .transgo-title .elementor-widget-container .elementor-heading-title::after {
	left: auto;
}

.rtl .cakelements-burger-menu .menu-item-has-children>a::after {
	left: 20px;
	right: auto !important;
	transform: rotate(180deg);
}

.rtl .cakelements-burger-menu .menu-item-has-children.menu-opened>a::after {
	transform: rotate(90deg);
}

.rtl .bdt-navbar-parent-indicator-yes .bdt-navbar-dropdown-nav>li.bdt-parent>a:after {
	transform: translate(50%,-50%) rotateY(180deg);
	right: auto;
}

.rtl .skin-hazel .bdt-post-slider-navigation-inner a svg {
	transform: rotate(180deg);
}

.rtl .bdt-ep-accordion-icon  {
    order: 1;
}

.widget_block {
	display: none;
}

.rtl .widget-area .widget .search-form .search-submit {
	transform: rotateY(180deg);
}

.rtl .widget-area .widget .search-form {
	padding-left: 0;
	padding-right: 10px;
}

.rtl .entry-date .posted-on a {
	right: 20px;
}

.rtl aside.widget-area section ul li::before {
	left: auto;
	right: 0;
}

.rtl aside.widget-area section ul li {
	padding-left: 0;
	padding-right: 15px;
}

.rtl aside.widget-area section ul li a, .rtl aside.widget-area section.widget_tag_cloud .tagcloud a, .rtl aside.widget-area section ul li.recentcomments, .rtl aside.widget-area section ul li span.post-date {
	text-align: right;
}

.rtl .transgo-comments-number::before, .rtl .entry-meta .byline::before,
.rtl .meta-items .entry-meta .cat-links::before, .rtl .meta-items .entry-meta .tags-links::before, .rtl .meta-items .entry-meta .byline::before, .rtl .meta-items .entry-meta .edit-link::before {
	left: 0;
  right: -25px;
}

.rtl .transgo-comments-number, .rtl .entry-meta .byline {
	margin-left: 0;
	margin-right: 25px;
}

.rtl .post-nav .next.page-numbers i,
.rtl .post-nav .prev.page-numbers i,
.rtl .icon-align-right i {
	transform: rotateY(180deg);
}

.rtl .error-404-main a i {
  padding-left: 10px;
	padding-right: 0;
}

.testimonial .bdt-testimonial-grid > .bdt-grid > * {
    padding-left: 0px !important;
}

